insert into public.services (slug, name, category, icon, short_description, description, features, process, pricing_model, price_amount, pricing_label, duration, is_active, is_featured) values
  ('plumbing-repair', 'Plumbing Repair', 'home-repairs', 'wrench', 'Leaks, clogs and fixture repairs handled by a vetted technician.', 'Fix dripping taps, slow drains, running toilets and minor pipe leaks. A technician assesses the issue on arrival, explains the fix and completes most repairs in a single visit.', array['On-site diagnosis before any work starts', 'Common parts carried on every visit', 'Clean-up after the job', 'Written summary of the work done']::text[], '[{"title":"Submit your request","description":"Describe what you need and pick a preferred date."},{"title":"Review & confirmation","description":"A coordinator confirms the time window and any access details."},{"title":"Service delivery","description":"The technician diagnoses, agrees the fix with you, and completes the repair."},{"title":"Wrap-up","description":"You confirm completion and the request moves to your history."}]'::jsonb, 'fixed', 89, 'From $89', '1–2 hours', true, true),
  ('electrical-inspection', 'Electrical Inspection', 'home-repairs', 'zap', 'A room-by-room safety check of outlets, switches and panels.', 'A structured inspection of your home''s visible electrical components, with a clear report of anything that needs attention and recommended next steps.', array['Outlet, switch and breaker panel checks', 'Prioritised findings report', 'Photos of any issues found', 'Recommendations with no obligation']::text[], '[{"title":"Submit your request","description":"Describe what you need and pick a preferred date."},{"title":"Review & confirmation","description":"We confirm the property size so the right amount of time is booked."},{"title":"Service delivery","description":"The inspector works through each room and documents findings."},{"title":"Wrap-up","description":"You confirm completion and the request moves to your history."}]'::jsonb, 'fixed', 129, 'From $129', '2–3 hours', true, false),
  ('appliance-installation', 'Appliance Installation', 'home-repairs', 'plug', 'Professional setup for washers, dishwashers and wall ovens.', 'Get new appliances connected, levelled and tested. Includes removal of packaging and a quick walkthrough of the main settings.', array['Connection and levelling', 'Function test after install', 'Packaging removed', 'Basic usage walkthrough']::text[], '[{"title":"Submit your request","description":"Describe what you need and pick a preferred date."},{"title":"Review & confirmation","description":"We check the appliance model and confirm any extra fittings needed."},{"title":"Service delivery","description":"The installer connects, tests and walks you through the appliance."},{"title":"Wrap-up","description":"You confirm completion and the request moves to your history."}]'::jsonb, 'fixed', 75, 'From $75', '1–2 hours', true, false),
  ('deep-home-cleaning', 'Deep Home Cleaning', 'cleaning', 'sparkles', 'Top-to-bottom cleaning, including kitchens and bathrooms.', 'A detailed clean covering hard-to-reach areas, appliances'' exteriors, bathrooms, floors and surfaces. Ideal before or after a move, or as a seasonal reset.', array['Kitchen and bathroom detailing', 'Inside-window and skirting cleaning', 'Eco-friendly products on request', 'Checklist-based quality review']::text[], '[{"title":"Submit your request","description":"Describe what you need and pick a preferred date."},{"title":"Review & confirmation","description":"We confirm the number of rooms and any focus areas."},{"title":"Service delivery","description":"A two-person team works through a room-by-room checklist."},{"title":"Wrap-up","description":"You confirm completion and the request moves to your history."}]'::jsonb, 'fixed', 149, 'From $149', '3–5 hours', true, true),
  ('office-cleaning', 'Office Cleaning', 'cleaning', 'building', 'Reliable cleaning for small offices and studios.', 'Scheduled or one-off cleaning for workspaces up to a medium-sized office, including desks, kitchens, meeting rooms and restrooms.', array['Flexible after-hours scheduling', 'Desk and shared-area sanitising', 'Waste and recycling handling', 'Consistent team where possible']::text[], '[{"title":"Submit your request","description":"Describe what you need and pick a preferred date."},{"title":"Review & confirmation","description":"We agree on scope, access and the best time window."},{"title":"Service delivery","description":"The team cleans to an agreed checklist and logs completion."},{"title":"Wrap-up","description":"You confirm completion and the request moves to your history."}]'::jsonb, 'hourly', 45, '$45 / hour', 'Varies by space', true, false),
  ('laptop-diagnostics', 'Laptop Diagnostics', 'it-support', 'laptop', 'Find out why your laptop is slow, noisy or misbehaving.', 'A technician runs hardware and software checks, identifies the root cause and recommends a fix. Simple software issues are often resolved during the session.', array['Hardware health checks', 'Startup and performance review', 'Malware scan', 'Plain-English findings report']::text[], '[{"title":"Submit your request","description":"Describe what you need and pick a preferred date."},{"title":"Review & confirmation","description":"We confirm the device type and whether you prefer remote or on-site."},{"title":"Service delivery","description":"The technician runs diagnostics and resolves quick fixes on the spot."},{"title":"Wrap-up","description":"You confirm completion and the request moves to your history."}]'::jsonb, 'fixed', 59, 'From $59', '1 hour', true, true),
  ('home-network-setup', 'Home Network Setup', 'it-support', 'wifi', 'Fast, secure Wi-Fi coverage across your whole home.', 'Set up or improve your router, mesh points and network security so every room gets a stable connection, with a guest network if you need one.', array['Coverage walk-through', 'Router and mesh configuration', 'Secure passwords and guest network', 'Speed test before and after']::text[], '[{"title":"Submit your request","description":"Describe what you need and pick a preferred date."},{"title":"Review & confirmation","description":"We ask about home size and current equipment."},{"title":"Service delivery","description":"The technician configures equipment and verifies coverage room by room."},{"title":"Wrap-up","description":"You confirm completion and the request moves to your history."}]'::jsonb, 'fixed', 99, 'From $99', '1–2 hours', true, false),
  ('data-backup-setup', 'Data Backup Setup', 'it-support', 'database', 'Automatic backups so your files are never a single point of failure.', 'Configure automatic local and cloud backups for your computers, with a tested restore so you know it works when you need it.', array['Backup plan tailored to your devices', 'Automatic schedules', 'Test restore included', 'Simple how-to guide left behind']::text[], '[{"title":"Submit your request","description":"Describe what you need and pick a preferred date."},{"title":"Review & confirmation","description":"We review the devices and how much data needs protecting."},{"title":"Service delivery","description":"The technician sets up backups and verifies a restore."},{"title":"Wrap-up","description":"You confirm completion and the request moves to your history."}]'::jsonb, 'fixed', 79, 'From $79', '1–2 hours', true, false),
  ('bookkeeping-setup', 'Bookkeeping Setup', 'business', 'calculator', 'Get your small-business books organised from day one.', 'A specialist sets up your chart of accounts, connects your bank feeds and shows you a simple monthly routine to keep things tidy.', array['Chart of accounts setup', 'Bank feed connection', 'Invoice and expense templates', 'Monthly routine walkthrough']::text[], '[{"title":"Submit your request","description":"Describe what you need and pick a preferred date."},{"title":"Review & confirmation","description":"A short intro call to understand your business."},{"title":"Service delivery","description":"The specialist configures your books and runs a walkthrough session."},{"title":"Wrap-up","description":"You confirm completion and the request moves to your history."}]'::jsonb, 'quote', null, 'Custom quote', '1–2 sessions', true, true),
  ('website-audit', 'Website Audit', 'business', 'globe', 'A practical review of speed, accessibility and clarity.', 'Receive a prioritised list of improvements for your website covering performance, accessibility, mobile usability and messaging.', array['Performance and Core Web Vitals review', 'Accessibility spot-checks', 'Mobile usability review', 'Prioritised action list']::text[], '[{"title":"Submit your request","description":"Describe what you need and pick a preferred date."},{"title":"Review & confirmation","description":"We confirm the site URL and your main goals."},{"title":"Service delivery","description":"The reviewer audits the site and delivers a report with a short call."},{"title":"Wrap-up","description":"You confirm completion and the request moves to your history."}]'::jsonb, 'fixed', 249, 'From $249', '3–5 business days', true, false),
  ('local-moving-assistance', 'Local Moving Assistance', 'moving', 'truck', 'Extra hands and a van for moves within the city.', 'A two-person crew with a van helps load, transport and unload your belongings for local moves, with basic furniture assembly available.', array['Two-person crew and van', 'Blankets and straps included', 'Basic furniture assembly', 'Hourly billing, no hidden extras']::text[], '[{"title":"Submit your request","description":"Describe what you need and pick a preferred date."},{"title":"Review & confirmation","description":"We confirm addresses, access and the approximate volume."},{"title":"Service delivery","description":"The crew loads, moves and unloads, then confirms with you on site."},{"title":"Wrap-up","description":"You confirm completion and the request moves to your history."}]'::jsonb, 'hourly', 110, '$110 / hour', 'Varies by move', true, false),
  ('career-coaching-session', 'Career Coaching Session', 'coaching', 'graduation', 'A focused one-to-one session on your next career step.', 'Work through a CV review, interview preparation or a career change plan with an experienced coach in a structured 60-minute session.', array['Pre-session questionnaire', '60-minute video session', 'Action plan sent afterwards', 'Optional follow-up session']::text[], '[{"title":"Submit your request","description":"Describe what you need and pick a preferred date."},{"title":"Review & confirmation","description":"We match you with a coach based on your goals."},{"title":"Service delivery","description":"You meet over video and receive a written action plan."},{"title":"Wrap-up","description":"You confirm completion and the request moves to your history."}]'::jsonb, 'fixed', 65, 'From $65', '60 minutes', false, false)
